/* generated common CSS: 00-tokens/tokens.css */
/* ============================================================
   lab-ui · canonical tokens · light theme
   ----------------------------------------------------------------
   Source-of-truth design tokens for the the platform block catalog.
   Extracted from source tokens (example.com light theme) +
   additive --font-mono from v5 (JetBrains Mono).
   ============================================================ */

:root {
  /* ─── Palette (raw brand colors) ─────────────────────────── */
  --color-black:        #1B1D25;
  --color-white:        #FFFFFF;
  --color-gray:         #BEC5D3;
  --color-gray-second:  #5C6474;
  --color-gray-blue:    #97A2B8;
  --color-gray-light:   #D9D9D9;

  --color-cyan:         #6BEAF9;
  --color-blue:         #4F95FF;
  --color-red:          #FF6C56;
  --color-green:        #7DDE8E;
  --color-orange:       #FFA72C;
  --color-magenta:      #EF5CFF;

  --color-black-bg:           #17171B;
  --color-gray-bg:            #F9F9F9;
  --color-light-card-bg:      #F7F7F74D;
  --color-header-footer-bg:   rgba(77, 79, 104, 0.20);

  --color-dark-card-bg:       linear-gradient(180deg, #20232D 0%, #2C2D3C 100%);
  --color-light-gray-stroke:  linear-gradient(179.96deg, #E0E8F4 0.03%, #D1D6DD 102.68%);
  --color-dark-gray-stroke:   linear-gradient(180deg, #454F6B 0%, #2F2F40 100%);

  /* ─── Brand CTA rainbow gradient (locked: v5 direction + stops) */
  --gradient-cta-ring:
    linear-gradient(250deg,
      rgba(107, 237, 249, 0)   4.98%,
      #6bedf9                 37.35%,
      #ffa72c                 72.51%,
      rgba(239, 92, 255, 0)   96.41%);

  /* ─── Typography ─────────────────────────────────────────── */
  --font-family:        "Vela Sans", sans-serif;
  --font-mono:          "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace;

  /* Type scale */
  --type-h1-size:       clamp(2.25rem, 5.2vw, 5rem);
  --type-h1-weight:     500;
  --type-h1-tracking:   -0.025em;
  --type-h1-leading:    1.04;

  --type-h2-size:       clamp(1.75rem, 3.4vw, 3.125rem);
  --type-h2-weight:     600;
  --type-h2-tracking:   -0.022em;
  --type-h2-leading:    1.15;

  --type-h3-size:       clamp(1.125rem, 1.6vw, 1.5625rem);
  --type-h3-weight:     600;
  --type-h3-tracking:   -0.015em;
  --type-h3-leading:    1.25;

  --type-h4-size:       1.125rem;
  --type-h4-weight:     600;
  --type-h4-tracking:   -0.01em;

  --type-lead-size:     clamp(1rem, 1.25vw, 1.25rem);
  --type-lead-weight:   400;
  --type-lead-leading:  1.5;

  --type-body-size:     1rem;
  --type-body-leading:  1.55;

  --type-eyebrow-size:  0.8125rem;
  --type-eyebrow-tracking: 0.12em;

  /* ─── Layout ─────────────────────────────────────────────── */
  --container-width:     105rem;
  --container-padding-x: 1.875rem;
  --header-height:       4.6875rem;

  /* Backdrop blur — header chrome */
  --backdrop-blur-header:    1.25rem;
  --backdrop-blur-table:     2.5rem;
  --backdrop-blur-ecosystem: 5rem;

  /* ─── Radii ──────────────────────────────────────────────── */
  --radius-pill:    6.25rem;
  --radius-card:    1.25rem;
  --radius-card-sm: 0.9375rem;

  /* ─── Motion ─────────────────────────────────────────────── */
  --transition-duration: 0.4s;
  --transition-fast:     0.2s;
  --transition-base:     var(--transition-duration);
  --transition-slow:     0.6s;

  /* ─── Elevation scale ────────────────────────────────────── */
  --shadow-1: 0 6px 16px -10px rgba(0, 0, 0, 0.18);
  --shadow-2: 0 14px 28px -22px rgba(0, 0, 0, 0.25);
  --shadow-3: 0 20px 48px -30px rgba(15, 17, 22, 0.28);
  --shadow-4: 0 24px 60px -26px rgba(27, 29, 37, 0.34);
  --shadow-glow: 0 0 32px -4px var(--cta-accent);          /* buttons + cards */
  --shadow-glow-soft: 0 0 18px -6px var(--cta-accent);      /* nav links, breadcrumb, locale chip */
  --shadow-glow-tight: 0 0 8px var(--cta-accent);           /* status / live dots */

  /* ─── Status palette (yes / partial / no / live) ─────────── */
  --color-status-yes:     #76D98F;
  --color-status-partial: #D7D9DC;
  --color-status-no:      #FF6B6B;
  --color-status-live:    #16A34A;

  /* ─── Surfaces · backdrop blur ───────────────────────────── */
  --backdrop-blur-panel: 1.125rem;  /* 18px — nav panel, table SW column */

  /* ─── Text accent (warm brown) ─────────────────────────────
     Pulled out so the first stop of --cta-secondary-fill is not
     re-used as a raw text color across blocks. */
  --color-text-accent:   #56422D;

  /* ─── Semantic tokens · LIGHT theme (canonical default) ──── */
  --color-bg:           var(--color-white);
  --color-bg-invert:    var(--color-black-bg);
  --color-text:         var(--color-gray-second);
  --color-heading:      var(--color-black);
  --color-link:         var(--color-black);
  --color-link-hover:   var(--color-gray-second);

  --header-bg:          var(--color-light-card-bg);
  --card-bg:            var(--color-gray-bg);
  --card-border:        var(--color-light-gray-stroke);
  --locale-selector-bg: var(--color-gray-bg);

  --button-primary-bg:        transparent;
  --button-primary-color:     var(--color-black);

  --button-secondary-bg:      transparent;
  --button-secondary-color:   var(--color-black);
  --button-secondary-border:  var(--color-black);

  --button-burger-button-bg:  var(--color-black);

  --input-bg:           var(--color-light-card-bg);

  /* ─── CTA · theme accent system ────────────────────────────
     --cta-accent is the page-wide interactive accent. It tints:
       · hover-rise glow (effect.hover-rise)
       · primary CTA outer hover glow (box-shadow)
       · secondary CTA always-on halo
       · italic accent word in hero titles
     --cta-secondary-fill is the filled background of secondary CTAs.
     Theme overrides go through [data-theme="..."] below. */
  --cta-accent:          var(--color-cyan);
  --cta-accent-soft:     rgba(107, 234, 249, 0.30);
  --cta-secondary-fill:  linear-gradient(90deg, #56422D 0%, #494938 100%);
  --cta-secondary-color: var(--color-white);
  --cta-secondary-border:rgba(255, 255, 255, 0.18);
}

/* ─── Theme overlays ───────────────────────────────────────────
   Set on <body data-theme="..."> or any wrapper. Cascades into
   every CTA, hover-rise effect, and accent text inside the scope.
   Names are color families, not industries — pick whichever fits. */

[data-theme="cyan"] {
  /* Default cyan — kept explicit so authors see the slot exists. */
  --cta-accent:          #6BEAF9;
  --cta-accent-soft:     rgba(107, 234, 249, 0.30);
  --cta-secondary-fill:  linear-gradient(90deg, #56422D 0%, #494938 100%);
}

[data-theme="green"] {
  --cta-accent:          #7DDE8E;
  --cta-accent-soft:     rgba(125, 222, 142, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #1E4D2F 0%, #2D5A3D 100%);
}

[data-theme="orange"] {
  --cta-accent:          #FFA72C;
  --cta-accent-soft:     rgba(255, 167, 44, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #5A3D1E 0%, #6B4A28 100%);
}

[data-theme="red"] {
  --cta-accent:          #FF6C56;
  --cta-accent-soft:     rgba(255, 108, 86, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #5A2D28 0%, #6B3A35 100%);
}

[data-theme="forest"] {
  --cta-accent:          #7DDE8E;
  --cta-accent-soft:     rgba(125, 222, 142, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #234728 0%, #345937 100%);
}

[data-theme="blue"] {
  --cta-accent:          #4F95FF;
  --cta-accent-soft:     rgba(79, 149, 255, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #1E3850 0%, #2C4A66 100%);
}

[data-theme="amber"] {
  --cta-accent:          #FFA72C;
  --cta-accent-soft:     rgba(255, 167, 44, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #4D3D1E 0%, #5C4A28 100%);
}

[data-theme="magenta"] {
  --cta-accent:          #EF5CFF;
  --cta-accent-soft:     rgba(239, 92, 255, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #3A2858 0%, #4B3370 100%);
}

/* ─── A11y · reduced motion ────────────────────────────────────
   Honour user's OS-level motion preference across every block. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

/* generated common CSS: 00-tokens/composition.css */
/* generated preview/CMS composition glue */
*, *::before, *::after {
  box-sizing: border-box;
}
html {
  min-width: 320px;
  scroll-behavior: smooth;
}
body {
  margin: 0;
  position: relative;
  min-width: 320px;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}
:root {
  --composition-section-y: clamp(4rem, 7vw, 6.5rem);
  --composition-section-y-compact: clamp(2.5rem, 5vw, 4rem);
}

/* Default vertical rhythm for every composed section.
   Blocks must NOT declare padding-block on their root class;
   the composer owns inter-section spacing.

   For section-wide decorative backgrounds (ambient tints, full-width
   surface colors): blocks declare the bg on the wrapper class
   `.composition-section--<block-id-slug>` so the fill extends through
   the composer-managed padding-block. The inner block class then owns
   content layout only. See hero.operational-diagram and
   mobile.4-card-glyph for canonical examples. */
.composition-section {
  position: relative;
  padding-block: var(--composition-section-y);
}

/* No edge-zero overrides: the hero needs padding-block-start so its
   content clears the sticky header (and the absolute-positioned
   breadcrumb chip that hangs from it), and the last section needs
   padding-block-end so it breathes above the footer. The default
   padding-block above gives both naturally. */

/* Closing accent sections are tighter at the top, with full rhythm
   at the bottom so the footer gets visual room. */
.composition-section--decorative-callout-band,
.composition-section--decorative-final-cta {
  padding-block: var(--composition-section-y-compact) var(--composition-section-y);
}
/* ─── Wrappers ───────────────────────────────────────────────
   Global wrapper primitive used by composer-injected markup AND
   by block-internal layouts that opt into `.container`. Block
   stylesheets may still redeclare `.<block> .container { … }`
   with the same calc — those are no-op duplicates but harmless. */
.container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

/* Narrow modifier for accent strips (callout, narrative). */
.container--narrow {
  max-width: calc(1100px + var(--container-padding-x) * 2);
}
a {
  color: inherit;
}
button,
input,
textarea,
select {
  font: inherit;
}
@media (max-width: 640px) {
  :root {
    --composition-section-y: 3.5rem;
    --composition-section-y-compact: 2.5rem;
  }
}

/* generated pricing CSS: servicewand-pricing-dynamic */
/* generated child CSS: 14-pricing/pricing.plans-flex/block.css */
/* lab-ui block · pricing.plans-flex
   Depends: 00-tokens/tokens.css. Light theme.
   Visual identity differs from pricing.plan-cards:
     · flat card surface (no internal white-on-gray gradient),
     · featured plan uses a 2px cta-accent ring + lifted shadow,
     · monospace price digits keep the ledger/operations feel,
     · sliding indicator inside the billing toggle,
     · per-card Save chip that fade-scales in for Annual,
     · price + billed-caption crossfade between billing modes,
     · static fallback slots controlled per slot via data-plan-visible.
     Dynamic mode can render any returned plan count. */

.pf-plans {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
  overflow-x: clip;
}
.pf-plans .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

/* ─── Header ────────────────────────────────────────────────── */
.pf-top {
  max-width: 58rem;
  margin-inline: auto;
  text-align: center;
  margin-bottom: 44px;
}
.pf-eyebrow {
  margin: 0 0 14px;
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  letter-spacing: var(--type-eyebrow-tracking);
  text-transform: uppercase;
  color: var(--color-text-accent);
}
.pf-title {
  margin: 0;
  color: var(--color-heading);
  font-size: var(--type-h1-size);
  font-weight: var(--type-h1-weight);
  line-height: var(--type-h1-leading);
  letter-spacing: var(--type-h1-tracking);
  overflow-wrap: break-word;
}
.pf-lede {
  max-width: 45rem;
  margin: 18px auto 0;
  font-size: 1.0625rem;
  line-height: 1.55;
}

/* ─── Toggle · sliding pill indicator ───────────────────────── */
.pf-toggle {
  position: relative;
  display: inline-grid;
  grid-template-columns: minmax(120px, 1fr) minmax(120px, 1fr);
  margin-top: 28px;
  padding: 4px;
  border: 1px solid rgba(146, 170, 205, 0.30);
  border-radius: var(--radius-pill);
  background: var(--color-gray-bg);
  isolation: isolate;
}
.pf-toggle::before {
  content: "";
  position: absolute;
  z-index: 0;
  top: 4px;
  bottom: 4px;
  left: 4px;
  width: calc(50% - 4px);
  border-radius: var(--radius-pill);
  background: var(--color-white);
  box-shadow: var(--shadow-1);
  transition: transform 0.34s cubic-bezier(0.32, 0.72, 0, 1);
}
.pf-plans[data-billing="annual"] .pf-toggle::before {
  transform: translateX(100%);
}
.pf-toggle-opt {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 18px;
  border: 0;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--color-text);
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  transition: color 0.24s ease;
}
.pf-toggle-opt.is-active {
  color: var(--color-heading);
}

.pf-note {
  margin: 14px 0 0;
  color: var(--color-gray-blue);
  font-size: 0.8125rem;
  line-height: 1.45;
}

/* ─── Grid · flexible static fallback slots ───────────────────
   Parent grid defines 8 explicit row tracks that match a card's
   8 logical sections (head, name, subtitle, price, billed, cta,
   features, disclaimer). Cards opt-in via grid-template-rows: subgrid
   so every card's track-N is sized to the tallest card's track-N —
   head row, subtitle row, price row, CTA row all align horizontally
   regardless of how long any one card's text is. The final track is
   1fr so each card stretches to fill the row-band's max height; the
   disclaimer self-aligns to the bottom of that flexible track.
   Dynamic mode disables the static subgrid tracks so any plan count can
   wrap naturally. */
.pf-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  /* Two explicit 8-track bands: when the grid wraps to two columns
     (tablet), the second card band still ends in a flexible track so
     its disclaimers bottom-align the same way as the first band. */
  grid-template-rows: repeat(7, auto) 1fr repeat(7, auto) 1fr;
  column-gap: 20px;
  /* Separates card bands when the grid wraps; inside a card the
     subgrid's own row-gap: 0 absorbs these gutters, so internal
     spacing is unaffected. */
  row-gap: 20px;
  max-width: 100%;
}
.pf-card[data-plan-visible="hide"] { display: none; }
.pf-card--skeleton {
  display: none;
  pointer-events: none;
}

.pf-plans[data-pricing-dynamic="true"]:not([data-pricing-state="dynamic"]):not([data-pricing-state="fallback"]) .pf-card--skeleton {
  display: grid;
}

.pf-plans[data-pricing-dynamic="true"]:not([data-pricing-state="dynamic"]):not([data-pricing-state="fallback"]) [data-plan-slot] {
  display: none;
}

.pf-skel {
  display: block;
  border-radius: var(--radius-pill);
  background: linear-gradient(90deg, rgba(146, 170, 205, 0.14), rgba(146, 170, 205, 0.28), rgba(146, 170, 205, 0.14));
  background-size: 200% 100%;
  animation: pf-skeleton 1.2s ease-in-out infinite;
}
.pf-skel--kicker { width: 38%; height: 22px; }
.pf-skel--title { width: 64%; height: 30px; margin-top: 18px; }
.pf-skel--text { width: 100%; height: 52px; margin-top: 12px; border-radius: 12px; }
.pf-skel--price { width: 54%; height: 42px; margin-top: 24px; }
.pf-skel--button { width: 100%; height: 46px; margin-top: 18px; }
.pf-skel--line { width: 92%; height: 14px; margin-top: 18px; }
.pf-skel--short { width: 68%; margin-top: 10px; }

@keyframes pf-skeleton {
  to { background-position-x: -200%; }
}

.pf-plans[data-pricing-state="dynamic"] .pf-grid {
  grid-template-rows: none;
  align-items: stretch;
}

.pf-plans[data-pricing-state="dynamic"] .pf-card {
  display: grid;
  grid-template-rows:
    minmax(26px, auto)
    auto
    minmax(4.35rem, auto)
    minmax(4.75rem, auto)
    minmax(4.125rem, auto)
    1fr
    auto;
  grid-row: auto;
}

.pf-plans[data-pricing-state="dynamic"] .pf-billed-stack {
  display: none;
}

.pf-plans[data-pricing-state="dynamic"] .pf-features {
  align-content: start;
}

.pf-plans[data-pricing-state="dynamic"] .pf-disclaimer {
  margin-top: auto;
}

.pf-plans[data-pricing-state="dynamic"] .pf-disclaimer:empty {
  display: none;
}

/* ─── Plan card · flat surface ──────────────────────────────── */
.pf-card {
  position: relative;
  display: grid;
  grid-template-rows: subgrid;
  grid-template-columns: minmax(0, 1fr);
  grid-row: span 8;
  row-gap: 0;
  min-width: 0;
  padding: 24px;
  border: 1px solid rgba(146, 170, 205, 0.28);
  border-radius: var(--radius-card);
  background: var(--color-white);
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}
.pf-card--muted {
  background: var(--color-gray-bg);
}
.pf-card--featured {
  border-color: var(--cta-accent);
  box-shadow: 0 0 0 1px var(--cta-accent), 0 22px 48px -30px rgba(27, 29, 37, 0.32);
  transform: translateY(-4px);
}
@media (hover: hover) {
  .pf-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-2);
  }
  .pf-card--featured:hover {
    transform: translateY(-6px);
  }
}

.pf-card-head {
  display: flex;
  min-height: 26px;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.pf-card-head:has(.pf-kicker:empty):has(.pf-badge:empty) {
  display: none;
}
.pf-kicker,
.pf-badge {
  display: inline-flex;
  max-width: 100%;
  align-items: center;
  min-height: 22px;
  border-radius: var(--radius-pill);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
}
.pf-kicker { color: var(--color-gray-blue); }
.pf-kicker:empty,
.pf-badge:empty {
  display: none;
}
.pf-badge {
  padding: 3px 9px;
  color: var(--color-heading);
  background: var(--cta-accent-soft);
}
.pf-card--featured .pf-badge { background: var(--cta-accent); }

.pf-name {
  margin: 18px 0 0;
  color: var(--color-heading);
  font-size: 1.5rem;
  font-weight: 650;
  line-height: 1.15;
  letter-spacing: -0.01em;
}
.pf-subtitle {
  min-height: 52px;
  margin: 8px 0 0;
  font-size: 0.9375rem;
  line-height: 1.45;
}

/* ─── Price block · crossfade between monthly/annual ────────── */
.pf-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 22px;
  color: var(--color-heading);
}
.pf-currency {
  font-size: 1rem;
  font-weight: 600;
}
.pf-amount-stack {
  display: inline-grid;
  align-items: baseline;
}
.pf-amount {
  grid-column: 1;
  grid-row: 1;
  font-family: var(--font-mono);
  font-size: 2.5rem;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.02em;
  transition:
    opacity 0.24s ease-out,
    transform 0.34s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: opacity, transform;
}
.pf-period {
  color: var(--color-gray-blue);
  font-size: 0.875rem;
}

/* Per-card Save chip · appears in Annual mode */
.pf-card-save {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: var(--radius-pill);
  background: var(--cta-accent-soft);
  color: var(--color-heading);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  transform-origin: left center;
  opacity: 0;
  transform: scale(0.78) translateY(2px);
  transition:
    opacity 0.22s ease-out,
    transform 0.22s ease-out;
  transition-delay: 0s;
}
.pf-card-save:empty { display: none; }
.pf-plans[data-billing="annual"] .pf-card-save {
  opacity: 1;
  transform: scale(1) translateY(0);
  transition:
    opacity 0.32s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.34s cubic-bezier(0.16, 1, 0.3, 1);
  transition-delay: 0.34s;
}

/* Billed caption crossfade · stacks monthly/annual in same cell */
.pf-billed-stack {
  display: grid;
  margin-top: 6px;
  min-height: 16px;
}
.pf-billed {
  grid-column: 1;
