  letter-spacing: 0.02em;
  transition:
    opacity 0.22s ease-out,
    transform 0.30s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Crossfade rules · outgoing leaves immediately, incoming arrives with a delay
   so the swap reads as motion instead of an instant flip. */
.pf-plans[data-billing="monthly"] [data-price-annual],
.pf-plans[data-billing="monthly"] [data-billed-annual] {
  opacity: 0;
  transform: translateY(-14px);
  pointer-events: none;
}
.pf-plans[data-billing="annual"] [data-price-monthly],
.pf-plans[data-billing="annual"] [data-billed-monthly] {
