.mx-feature-hint:empty { display: none; }

.mx-mobile-plan { display: none; }
.mx-value {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  min-height: 19px;
  position: relative;
}

/* ─── Cell states ───────────────────────────────────────────── */
.mx-cell[data-state="yes"]     .mx-value::before,
.mx-cell[data-state="partial"] .mx-value::before {
  content: "";
  display: inline-block;
  width: 19px;
  height: 19px;
  border-radius: 999px;
  flex: 0 0 19px;
}
.mx-cell[data-state="yes"]     .mx-value::before { background: var(--color-status-yes, #76D98F); }
.mx-cell[data-state="partial"] .mx-value::before { background: var(--color-status-partial, #D7D9DC); }
.mx-cell[data-state="yes"]     .mx-value::after,
.mx-cell[data-state="partial"] .mx-value::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 8px;
  width: 8px;
  height: 4px;
  border-left: 2px solid #F9F9F9;
  border-bottom: 2px solid #F9F9F9;
  border-radius: 1px;
  transform: rotate(-45deg);
}
.mx-cell[data-state="yes"] .mx-value:empty,
.mx-cell[data-state="partial"] .mx-value:empty {
  gap: 0;
}
/* "no" reads as a quiet gray dash, not a red X: a column of negative
   marks visually punishes the entry plan. */
.mx-cell[data-state="no"] .mx-value { color: var(--color-gray-blue); }
.mx-cell[data-state="no"] .mx-value:empty::before { content: "—"; }
.mx-cell[data-state="empty"] .mx-value { color: var(--color-gray-blue); }
.mx-cell[data-state="empty"] .mx-value:empty::before { content: "—"; }

/* ─── Group title row ───────────────────────────────────────── */
.mx-group { display: contents; }
.mx-group[data-group-visible="hide"] { display: none; }
.mx-row[data-row-visible="hide"] { display: none; }
.mx-group-title {
  grid-column: 1 / -1;
  padding: 18px 18px 10px;
  background: var(--color-white);
  color: var(--color-text-accent);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  border-bottom: 1px solid rgba(146, 170, 205, 0.20);
  border-top: 1px solid rgba(146, 170, 205, 0.16);
}
.mx-group:first-of-type .mx-group-title { border-top: 0; }

/* ─── Collapsible row groups (desktop opt-in) ───────────────── */
.mx-matrix[data-groups-collapsible="on"] .mx-group-title {
  display: flex;
  align-items: center;
  cursor: pointer;
  user-select: none;
  transition: color var(--transition-fast);
}
.mx-matrix[data-groups-collapsible="on"] .mx-group-title:hover {
  color: var(--color-heading);
}
.mx-group-chev {
  margin-left: auto;
  width: 8px;
  height: 8px;
  flex: 0 0 auto;
  /* down = expanded, right = collapsed */
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translateY(-2px) rotate(45deg);
  transition: transform var(--transition-fast);
  opacity: 0.65;
}
.mx-matrix[data-groups-collapsible="on"] .mx-group[data-group-collapsed="true"] .mx-group-chev {
  transform: rotate(-45deg);
}
.mx-matrix[data-groups-collapsible="on"] .mx-group[data-group-collapsed="true"] > .mx-row { display: none; }

/* ─── CTA row · closes the table with an action per plan ────── */
.mx-row--cta[data-row-visible="hide"] { display: none; }
.mx-row--cta { background: var(--color-gray-bg); }
.mx-row--cta .mx-cell--feature {
  color: var(--color-gray-blue);
  font-size: 0.8125rem;
}
.mx-cta {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 6px 12px;
  border-radius: var(--radius-pill);
  background:
    linear-gradient(var(--color-white), var(--color-white)) padding-box,
    var(--gradient-cta-ring) border-box;
  border: 1px solid transparent;
  color: var(--color-heading);
  font-size: 0.875rem;
  font-weight: 650;
  line-height: 1.2;
  text-decoration: none;
  text-align: center;
  /* Fills the cell and wraps: a nowrap pill overflows the narrow plan
     columns on tablet widths. */
  white-space: normal;
  overflow-wrap: break-word;
  min-width: 0;
  transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}
.mx-cta:hover {
  transform: translateY(-1px);
  box-shadow: 0 0 32px -4px var(--cta-accent, #6BEAF9);
}
.mx-cta[aria-disabled="true"] {
  cursor: not-allowed;
  color: var(--color-gray-blue);
  background: var(--color-gray-bg);
  border-color: rgba(146, 170, 205, 0.28);
  box-shadow: none;
  opacity: 0.72;
}
.mx-cta[aria-disabled="true"]:hover {
  transform: none;
  box-shadow: none;
}
.mx-cta:empty { display: none; }

/* ─── Accordion shell (mobile) ─────────────────────────────── */
.mx-shell--accordion { display: none; }

@media (max-width: 720px) {
  .mx-matrix .container { padding-inline: 18px; }
  .mx-shell--table { display: none; }
  .mx-shell--accordion {
    display: grid;
    gap: 10px;
  }
  .mx-acc {
    border: 1px solid rgba(146, 170, 205, 0.26);
    border-radius: var(--radius-card);
    background: var(--color-white);
    overflow: hidden;
  }
  .mx-acc[open] { box-shadow: var(--shadow-1); }
  .mx-acc-summary {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 18px 20px;
    cursor: pointer;
    list-style: none;
  }
  .mx-acc-summary::-webkit-details-marker { display: none; }
  .mx-acc-name {
    flex: 1;
    color: var(--color-heading);
    font-size: 1.0625rem;
    font-weight: 650;
  }
  .mx-acc-tag {
    padding: 3px 9px;
    border-radius: var(--radius-pill);
    background: var(--cta-accent-soft);
    color: var(--color-heading);
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }
  .mx-acc-chev {
    width: 10px;
    height: 10px;
    border-right: 2px solid var(--color-gray-blue);
    border-bottom: 2px solid var(--color-gray-blue);
    transform: rotate(45deg);
    transition: transform var(--transition-fast);
  }
  .mx-acc[open] .mx-acc-chev { transform: rotate(-135deg); }
  .mx-acc-body {
    padding: 0 20px 18px;
    border-top: 1px solid rgba(146, 170, 205, 0.18);
  }
  .mx-acc-group { padding-top: 14px; }
  .mx-acc-group[data-group-visible="hide"] { display: none; }
  .mx-acc-group-title {
    margin: 0 0 8px;
    color: var(--color-text-accent);
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    letter-spacing: 0.10em;
    text-transform: uppercase;
  }
  .mx-acc-list { margin: 0; padding: 0; display: grid; gap: 4px; }
  .mx-acc-item {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 12px;
    padding: 8px 0;
    border-bottom: 1px dashed rgba(146, 170, 205, 0.22);
  }
  .mx-acc-item[data-row-visible="hide"] { display: none; }
  .mx-acc-item:last-child { border-bottom: 0; }
  .mx-acc-item dt {
    color: var(--color-text);
    font-size: 0.875rem;
  }
  .mx-acc-item dd {
    margin: 0;
    color: var(--color-heading);
    font-size: 0.875rem;
    font-weight: 600;
    text-align: right;
  }
  .mx-acc-item dd[data-state="yes"],
  .mx-acc-item dd[data-state="partial"] {
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    min-height: 19px;
    position: relative;
  }
  .mx-acc-item dd[data-state="yes"]::before,
  .mx-acc-item dd[data-state="partial"]::before {
    content: "";
    display: inline-block;
    width: 19px;
    height: 19px;
    border-radius: 999px;
    flex: 0 0 19px;
  }
  .mx-acc-item dd[data-state="yes"]::before { background: var(--color-status-yes, #76D98F); }
  .mx-acc-item dd[data-state="partial"]::before { background: var(--color-status-partial, #D7D9DC); }
  .mx-acc-item dd[data-state="yes"]::after,
  .mx-acc-item dd[data-state="partial"]::after {
    content: "";
    position: absolute;
    left: 5px;
    top: 8px;
    width: 8px;
    height: 4px;
    border-left: 2px solid #F9F9F9;
    border-bottom: 2px solid #F9F9F9;
    border-radius: 1px;
    transform: rotate(-45deg);
  }
  .mx-acc-item dd[data-state="no"] { color: var(--color-gray-blue); font-weight: 400; }
  .mx-acc-item dd[data-state="no"]:empty::before { content: "—"; }
  .mx-acc-item dd[data-state="empty"] { color: var(--color-gray-blue); font-weight: 400; }
  .mx-acc-item dd[data-state="empty"]:empty::before { content: "—"; }
  .mx-acc-item dd[data-state="yes"]:empty,
  .mx-acc-item dd[data-state="partial"]:empty {
    gap: 0;
  }
  .mx-acc-cta {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 44px;
    margin-top: 16px;
    padding: 0 16px;
    border-radius: var(--radius-pill);
    background:
      linear-gradient(var(--color-white), var(--color-white)) padding-box,
      var(--gradient-cta-ring) border-box;
    border: 1px solid transparent;
    color: var(--color-heading);
    font-size: 0.9375rem;
    font-weight: 650;
    text-decoration: none;
    transition: transform var(--transition-fast), box-shadow var(--transition-fast);
  }
  .mx-acc-cta:hover {
    transform: translateY(-1px);
    box-shadow: 0 0 32px -4px var(--cta-accent, #6BEAF9);
  }
  .mx-acc-cta[aria-disabled="true"] {
    cursor: not-allowed;
    color: var(--color-gray-blue);
    background: var(--color-gray-bg);
    border-color: rgba(146, 170, 205, 0.28);
    box-shadow: none;
    opacity: 0.72;
  }
  .mx-acc-cta[data-row-visible="hide"], .mx-acc-cta:empty { display: none; }
}

/* ─── Accessibility ─────────────────────────────────────────── */
.mx-cta:focus-visible,
.mx-acc-cta:focus-visible,
.mx-acc-summary:focus-visible,
.mx-matrix[data-groups-collapsible="on"] .mx-group-title:focus-visible {
  outline: 2px solid var(--cta-accent);
  outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  .mx-matrix *,
  .mx-matrix *::before,
  .mx-matrix *::after {
    transition-duration: 0.01ms !important;
  }
}

.mx-disclaimer {
  margin: 22px 0 0;
  color: var(--color-gray-blue);
  font-size: 0.8125rem;
  line-height: 1.5;
  text-align: center;
}


